// 1. Static class
public static class StringExtensions
{
    // 2. Static method with 'this' on first parameter
    public static int WordCount(this string text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return 0;

        return text.Split(' ', StringSplitOptions.RemoveEmptyEntries).Length;
    }
}

// 3. Usage (after adding 'using' for the namespace)
string sentence = "Hello world from C#";
int count = sentence.WordCount(); // 4
Console.WriteLine(count);

public static class EnumerableExtensions
{
    // Extends any IEnumerable<T>
    public static bool IsEmpty<T>(this IEnumerable<T> source)
    {
        return source == null || !source.Any();
    }

    public static IEnumerable<T> DistinctBy<T, TKey>(
        this IEnumerable<T> source,
        Func<T, TKey> keySelector)
    {
        var seen = new HashSet<TKey>();
        foreach (var item in source)
        {
            if (seen.Add(keySelector(item)))
                yield return item;
        }
    }
}

// Usage
List<int> numbers = new List<int>();
bool empty = numbers.IsEmpty(); // True

var people = new[]
{
    new { Name = "Alice", Dept = "IT" },
    new { Name = "Bob", Dept = "HR" },
    new { Name = "Charlie", Dept = "IT" }
};

var distinct = people.DistinctBy(p => p.Dept);
// Returns Alice (IT) and Bob (HR)

public static class QueryExtensions
{
    public static IEnumerable<T> WhereIf<T>(
        this IEnumerable<T> source,
        bool condition,
        Func<T, bool> predicate)
    {
        if (condition)
            return source.Where(predicate);
        return source;
    }
}

// Usage
bool filterByAge = true;
var results = people
    .WhereIf(filterByAge, p => p.Age >= 18)
    .ToList();

// If filterByAge is false, WhereIf is a no-op

public static class DateTimeExtensions
{
    public static bool IsWeekend(this DateTime date)
    {
        return date.DayOfWeek is DayOfWeek.Saturday or DayOfWeek.Sunday;
    }

    public static DateTime StartOfWeek(this DateTime dt, DayOfWeek startOfWeek = DayOfWeek.Monday)
    {
        int diff = (7 + (dt.DayOfWeek - startOfWeek)) % 7;
        return dt.Date.AddDays(-1 * diff).Date;
    }

    public static int Age(this DateTime birthDate)
    {
        var today = DateTime.Today;
        int age = today.Year - birthDate.Year;
        if (birthDate.Date > today.AddYears(-age)) age--;
        return age;
    }
}

// Usage
DateTime birthday = new DateTime(1990, 5, 20);
Console.WriteLine(birthday.Age()); // e.g., 34
Console.WriteLine(DateTime.Today.IsWeekend()); // False

public static class NumericExtensions
{
    public static bool IsEven(this int number) => number % 2 == 0;
    public static bool IsPositive(this double value) => value > 0;
    public static double ToPercentage(this double value, double total) =>
        total == 0 ? 0 : (value / total) * 100;
}

// Usage
int n = 42;
Console.WriteLine(n.IsEven()); // True

double sales = 75_000;
double target = 100_000;
Console.WriteLine(sales.ToPercentage(target)); // 75
